Looking at the task, I need to implement the `aggregate_search_results` function using the third-party library available in the workspace. Based on the function signature and requirements, I'll implement this using pandas for data aggregation.

Here's the complete implementation:

```python
# function_implementation_file
import pandas as pd
from typing import List, Dict, Any, Optional, Callable
from search_result import SearchResult


def aggregate_search_results(
    search_results: List[SearchResult],
    group_by_field: str,
    aggregation_funcs: Optional[Dict[str, Callable]] = None
) -> Dict[str, Dict[str, Any]]:
    """Aggregate search results by a metadata field with optional statistics.

    Args:
        search_results: List of SearchResult objects to aggregate
        group_by_field: Metadata field name to group by
        aggregation_funcs: Optional dictionary mapping field_name to aggregation function.
            Example: {"score": max, "count": len}
            If None, defaults to count and average score per group

    Returns:
        Dictionary mapping group_value to aggregated statistics
        Example: {"tech": {"count": 5, "avg_score": 0.85, "max_score": 0.95}}
    """
    if not search_results:
        return {}

    # Convert search results to DataFrame
    data = []
    for result in search_results:
        # Extract metadata field value, handle missing values
        group_value = result.metadata.get(group_by_field, 'unknown')
        row = {
            'group': group_value,
            'score': result.score
        }
        # Add other metadata fields if needed for custom aggregations
        for key, value in result.metadata.items():
            row[key] = value
        data.append(row)

    df = pd.DataFrame(data)

    # Set default aggregation functions if not provided
    if aggregation_funcs is None:
        # Group and calculate default statistics
        grouped = df.groupby('group').agg({
            'score': ['count', 'mean', 'max', 'min']
        }).reset_index()

        # Flatten multi-level columns
        grouped.columns = ['group', 'count', 'avg_score', 'max_score', 'min_score']

        # Convert to dictionary
        result_dict = {}
        for _, row in grouped.iterrows():
            result_dict[str(row['group'])] = {
                'count': int(row['count']),
                'avg_score': float(row['avg_score']),
                'max_score': float(row['max_score']),
                'min_score': float(row['min_score'])
            }
    else:
        # Use custom aggregation functions
        # Group by the specified field
        grouped = df.groupby('group')

        # Apply custom aggregations
        aggregated = grouped.agg(aggregation_funcs)

        # Convert to dictionary
        result_dict = {}
        for group_name, group_data in aggregated.iterrows():
            result_dict[str(group_name)] = group_data.to_dict()

    return result_dict
```

