/**
 * description: inventory_bulk_write_and_read.
 * This function demonstrates how to perform bulk write and read operations on an inventory table.
 * It first drops and recreates the table, then writes the given items to the table.
 * Finally, it reads back the items with quantity > 50, orders them by quantity in descending order,
 * and returns true if at least one item is found.
 * Returns: bool.
 */
bool inventory_bulk_write_and_read(const std::vector<Inventory>& items) {
    // Create database storage
    auto storage = make_storage("test_db.sqlite",
        make_table("Inventory",
            make_column("item_id", &Inventory::item_id, primary_key()),
            make_column("name", &Inventory::name),
            make_column("quantity", &Inventory::quantity),
            make_column("location", &Inventory::location)
        )
    );

    // Drop and recreate the table
    storage.drop_table("Inventory");
    storage.create_table("Inventory");

    // Write batch of items using transaction for efficiency
    {
        auto transaction = storage.transaction();

        // Bulk insert all items
        storage.insert_range(items.begin(), items.end());

        transaction.commit();
    }

    // Read items with quantity > 50, ordered by quantity descending
    auto filtered_items = storage.select(
        columns(&Inventory::item_id, &Inventory::name, &Inventory::quantity, &Inventory::location),
        where(greater_than(&Inventory::quantity, 50)),
        order_by(&Inventory::quantity).desc()
    );

    // Return true if at least one item is found
    return !filtered_items.empty();
}

}  // namespace inventory_bulk_write_and_read
