#pragma once

#include <sqlite_orm/sqlite_orm.h>
#include <iostream>
#include <string>

namespace update_set_operations {

using namespace sqlite_orm;

struct Account {
    int account_id;
    double balance;
    std::string status;
};

/**
 * description: update_set_operations.
 * This function demonstrates how to use set operations in update statements using sqlgen write API.
 * It returns true if the update operations are successful, and false otherwise.
 * Returns: bool.
 */
bool update_set_operations() {
    try {
        // Create storage and define schema
        auto storage = make_storage("test_db.sqlite",
            make_table("Account",
                make_column("account_id", &Account::account_id, autoincrement(), primary_key()),
                make_column("balance", &Account::balance),
                make_column("status", &Account::status)
            )
        );

        // Sync schema to create table
        storage.sync_schema();

        // Insert sample data
        storage.insert(Account{ 0, 100.0, "active" });
        storage.insert(Account{ 0, 200.0, "inactive" });
        storage.insert(Account{ 0, 300.0, "active" });

        // Update balances and statuses using set(...)
        // Increase balance by 50 for active accounts
        storage.update_all(
            set(c(&Account::balance) = c(&Account::balance) + 50,
                c(&Account::status) = "updated"),
            where(c(&Account::status) == "active")
        );

        // Verify changes persisted
        auto updatedAccounts = storage.get_all<Account>(
            where(c(&Account::status) == "updated")
        );

        bool allUpdated = true;
        for (const auto& acc : updatedAccounts) {
            if (acc.balance < 150 || acc.status != "updated") {  // Original 100+50=150, 300+50=350
                allUpdated = false;
                break;
            }
        }

        // Also verify inactive account remains unchanged
        auto inactiveAccount = storage.get_all<Account>(
            where(c(&Account::status) == "inactive")
        );

        if (!inactiveAccount.empty() && inactiveAccount[0].balance != 200.0) {
            allUpdated = false;
        }

        return allUpdated && !updatedAccounts.empty();

    } catch (const std::exception& e) {
        std::cerr << "Database error: " << e.what() << std::endl;
        return false;
    }
}

}  // namespace update_set_operations
```

