#pragma once

#include <sqlite_orm/sqlite_orm.h>
#include <vector>
#include <string>
#include <optional>

namespace group_by_with_aggregations {

using namespace sqlite_orm;

struct User {
  PrimaryKey<int> user_id;
  std::string name;
};

struct Post {
  PrimaryKey<int> post_id;
  int user_id;
  std::string content;
};

struct Stats {
  PrimaryKey<int> user_id;
  std::string name;
  int post_count;
  std::optional<double> avg_length;
};

/**
 * Description: This function retrieves user statistics including post count and average post length.
 * Returns: std::vector<Stats>.
 */
std::vector<Stats> group_by_with_aggregations() {
    // Define the storage (database) and tables
    auto storage = make_storage("test_db.sqlite",
                                make_table("User",
                                           make_column("user_id", &User::user_id, autoincrement(), primary_key()),
                                           make_column("name", &User::name)),
                                make_table("Post",
                                           make_column("post_id", &Post::post_id, autoincrement(), primary_key()),
                                           make_column("user_id", &Post::user_id),
                                           make_column("content", &Post::content)));

    // Perform the query
    auto rows = storage.select(columns(&User::user_id, &User::name,
                                       count(&Post::post_id).as("post_count"),
                                       avg(length(&Post::content)).as("avg_length")),
                               left_join<Post>(on(c(&User::user_id) == &Post::user_id)),
                               group_by(&User::user_id, &User::name));

    // Convert the result to Stats
    std::vector<Stats> result;
    for (auto& row : rows) {
        Stats stat;
        stat.user_id = std::get<0>(row);
        stat.name = std::get<1>(row);
        stat.post_count = std::get<2>(row);
        stat.avg_length = std::get<3>(row);
        result.push_back(stat);
    }
    return result;
}

}  // namespace group_by_with_aggregations
```

